+        .font_weight(FontWeight::SEMIBOLD)
+}
+
+pub fn editorial_dateline() -> String {
+    dateline(Local::now().date_naive())
+}
+
+fn dateline(date: NaiveDate) -> String {
+    let day = date.day();
+    let suffix = match day % 100 {
+        11..=13 => "th",
+        _ => match day % 10 { 1 => "st", 2 => "nd", 3 => "rd", _ => "th" },
+    };
+    format!("Vol. I · No. {} · {}, the {day}{suffix} of {}, {}",
+        date.ordinal(), date.format("%A"), date.format("%B"), date.year())
+}
+
+#[cfg(test)]
+mod tests {
+    #[test]
+    fn dateline_matches_the_reference_masthead() {
+        assert_eq!(super::dateline(chrono::NaiveDate::from_ymd_opt(2026, 10, 4).unwrap()),
+            "Vol. I · No. 277 · Sunday, the 4th of October, 2026");
+    }
+}
