+//! Native proof preparation reuses the source app's editorial settings.
+use anyhow::{Context, Result, anyhow};
+use gpui_kit::AssetSource;
+use serde_json::Value;
+use std::sync::{Arc, OnceLock};
+use twyne_desktop::{assets::TwyneAssets, native_typst::{CompileRequest, CompileResult, TypstAsset, TypstEngine}, semantic_bridge::SemanticBridge, workspace::WorkspaceDocument};
+
+#[derive(Default)]
+pub struct NativeCompiler {
+    engine: OnceLock<Result<TypstEngine, String>>,
+}
+
+pub struct ProofBuild {
+    pub compilation: CompileResult,
+    /// The real bounded visual projection of the canonical source. Only a
+    /// successful, current compile may be applied to the workspace.
+    pub html: Option<String>,
+}
+
+impl NativeCompiler {
+    pub fn compile(&self, generation: u64, source: Arc<str>, workspace: Option<&WorkspaceDocument>, title: &str) -> Result<ProofBuild> {
+        let engine = self.engine.get_or_init(|| TypstEngine::new().map_err(|error| format!("{error:#}"))).as_ref().map_err(|error| anyhow!("{error}"))?;
+        let bridge = SemanticBridge::discover()?;
+        let mut payload = serde_json::json!({"title":title, "html":"", "typstSource":source.as_ref()});
+        if let Some(workspace) = workspace {
+            payload["html"] = Value::String(workspace.content.html.clone());
+            if let Some(layout) = &workspace.folio.layout { payload["layout"] = serde_json::to_value(layout)?; }
+            if let Some(header) = &workspace.folio.header { payload["header"] = Value::String(header.clone()); }
+            if let Some(footer) = &workspace.folio.footer { payload["footer"] = Value::String(footer.clone()); }
+        }
+        let prepared = bridge.prepare_proof(&source, &payload)?;
+        let mut request = CompileRequest::new(generation, source.clone());
+        request.prepared_source = Some(prepared.source.into());
+        for asset in prepared.decorations {
+            let bytes = TwyneAssets.load(&asset.url)?.with_context(|| format!("The original artwork is unavailable: {}", asset.url))?;
+            request.assets.push(TypstAsset::new(asset.path, Arc::<[u8]>::from(bytes.as_ref())));
+        }
+        let compilation = engine.compile(request);
+        let html = if compilation.proof.is_some() { Some(bridge.project(&source)?.html) } else { None };
+        Ok(ProofBuild { compilation, html })
+    }
+}
