+        match history.checkpoint(Arc::new(self.active_document().clone()), CheckpointOptions::automatic(timestamp())) {
+            Ok(outcome) => self.revision_timeline = outcome.timeline,
+            Err(error) => self.notice = Some(format!("Your manuscript is saved. Version history needs attention: {error:#}")),
+        }
+        self.update_revision_capabilities(cx);
+    }
+
+    fn load_active_revision_history(&mut self, cx: &mut Context<Self>) {
+        self.revision_generation = self.revision_generation.saturating_add(1);
+        if self.revision_view.as_ref().is_some_and(|view| view.read(cx).current().id != self.active) {
+            self.revision_subscription = None;
+            self.revision_view = None;
+        }
+        self.revision_timeline = Arc::new(RevisionTimeline::new(self.active));
+        if let Some(history) = &self.revision_store {
