+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+enum TokenKind { Keyword, String, Number, Heading, Comment }
+
+#[derive(Clone, Debug, PartialEq, Eq)]
+struct Token { range: Range<usize>, kind: TokenKind }
+
+#[derive(Clone, Debug, PartialEq, Eq)]
+struct LexedLine {
+    text: String,
+    incoming_comment: bool,
+    outgoing_comment: bool,
+    tokens: Vec<Token>,
+}
+
+fn word(byte: u8) -> bool { byte.is_ascii_alphanumeric() || byte == b'_' }
+
+fn lex_line(text: String, mut comment: bool) -> LexedLine {
+    let incoming_comment = comment;
+    let bytes = text.as_bytes();
+    let mut tokens = Vec::new();
+    let mut at = 0;
+    while at < bytes.len() {
+        let start = at;
+        let remaining = &text[at..];
+        let kind = if comment {
+            if let Some(end) = remaining.find("*/") {
+                at += end + 2;
+                comment = false;
+            } else { at = bytes.len(); }
+            Some(TokenKind::Comment)
+        } else if remaining.starts_with("//") {
+            at = bytes.len();
+            Some(TokenKind::Comment)
+        } else if remaining.starts_with("/*") {
+            at += 2;
+            comment = true;
+            if let Some(end) = text[at..].find("*/") {
+                at += end + 2;
+                comment = false;
+            } else { at = bytes.len(); }
+            Some(TokenKind::Comment)
+        } else if bytes[at] == b'"' {
+            at += 1;
+            while at < bytes.len() {
+                if bytes[at] == b'\\' {
+                    at += 1;
+                    if at < bytes.len() { at += text[at..].chars().next().unwrap().len_utf8(); }
+                } else if bytes[at] == b'"' { at += 1; break; }
+                else { at += text[at..].chars().next().unwrap().len_utf8(); }
+            }
+            Some(TokenKind::String)
+        } else if at == 0 && bytes[at] == b'=' {
+            let mut end = at;
+            while end < bytes.len() && bytes[end] == b'=' { end += 1; }
+            if text[end..].chars().next().is_some_and(char::is_whitespace) {
+                at = bytes.len();
+                Some(TokenKind::Heading)
+            } else { at += 1; None }
+        } else if bytes[at] == b'#' && bytes.get(at + 1).is_some_and(|byte| byte.is_ascii_alphabetic() || *byte == b'_') {
+            at += 2;
+            while at < bytes.len() && (word(bytes[at]) || bytes[at] == b'-') { at += 1; }
+            Some(TokenKind::Keyword)
+        } else if bytes[at].is_ascii_digit() && (at == 0 || !word(bytes[at - 1])) {
+            at += 1;
+            while at < bytes.len() && bytes[at].is_ascii_digit() { at += 1; }
+            if bytes.get(at) == Some(&b'.') && bytes.get(at + 1).is_some_and(u8::is_ascii_digit) {
+                at += 1;
+                while at < bytes.len() && bytes[at].is_ascii_digit() { at += 1; }
+            }
+            if let Some(unit) = ["pt", "em", "cm", "mm", "in", "%"].into_iter().find(|unit| text[at..].starts_with(unit)) {
+                at += unit.len();
+            }
+            Some(TokenKind::Number)
+        } else if bytes[at].is_ascii_alphabetic() && (at == 0 || !word(bytes[at - 1])) {
+            at += 1;
+            while at < bytes.len() && word(bytes[at]) { at += 1; }
+            ["true", "false", "none", "auto", "let", "set", "show", "import", "include"]
+                .contains(&&text[start..at]).then_some(TokenKind::Keyword)
+        } else {
+            at += text[at..].chars().next().unwrap().len_utf8();
+            None
+        };
+        if let Some(kind) = kind { tokens.push(Token { range: start..at, kind }); }
+    }
+    LexedLine { text, incoming_comment, outgoing_comment: comment, tokens }
+}
