+struct TypstHighlighter {
+    cache: LexCache,
+    colors: theme::Palette,
+}
+
+impl TypstHighlighter {
+    fn style(&self, kind: TokenKind) -> HighlightStyle {
+        HighlightStyle {
+            color: Some(rgb(match kind {
+                TokenKind::Keyword => self.colors.vermilion,
+                TokenKind::String => self.colors.cobalt,
+                TokenKind::Number => self.colors.writer_note,
+                TokenKind::Heading => self.colors.ink,
+                TokenKind::Comment => self.colors.ink_light,
+            }).into()),
+            font_weight: (kind == TokenKind::Heading).then_some(FontWeight::SEMIBOLD),
+            font_style: (kind == TokenKind::Comment).then_some(FontStyle::Italic),
+            ..Default::default()
+        }
+    }
+}
+
+impl InputHighlighter for TypstHighlighter {
+    fn language(&self) -> SharedString { "typst".into() }
+
+    fn update(&mut self, edit: Option<InputEdit>, text: &Rope, _: bool, _: &mut Window, cx: &mut Context<EditorState>) {
+        self.colors = *theme::palette(cx);
+        self.cache.update(edit, text);
+    }
+
+    fn styles(&self, range: &Range<usize>, _: &dyn HighlightStyleResolver) -> Vec<(Range<usize>, HighlightStyle)> {
+        let mut result = Vec::new();
+        let mut cursor = range.start;
+        let start_line = self.cache.text.offset_to_point(range.start).row;
+        let end_line = self.cache.text.offset_to_point(range.end).row.min(self.cache.lines.len().saturating_sub(1));
+        for row in start_line..=end_line {
+            let offset = self.cache.text.line_start_offset(row);
+            let Some(line) = self.cache.lines.get(row).and_then(Option::as_ref) else { continue; };
+            for token in &line.tokens {
+                let start = (offset + token.range.start).max(range.start);
+                let end = (offset + token.range.end).min(range.end);
+                if start >= end { continue; }
+                if cursor < start { result.push((cursor..start, HighlightStyle::default())); }
+                result.push((start..end, self.style(token.kind)));
+                cursor = end;
+            }
+        }
+        if cursor < range.end { result.push((cursor..range.end, HighlightStyle::default())); }
+        result
+    }
+
+    fn fold_ranges(&self, text: &Rope) -> Vec<FoldRange> {
+        if text.slice_line(0).to_string() != "// twyne-document:1" { return Vec::new(); }
+        self.cache.lines.iter().enumerate().skip(1)
+            .find(|(_, line)| line.as_ref().is_some_and(|line| line.text == "// twyne-document:body"))
+            .map_or_else(Vec::new, |(row, _)| vec![FoldRange::new(0, row)])
+    }
+}
