+        if !self.source_writable() { return; }
+        self.source.update(cx, |state, cx| {
+            let selected = state.selected_range();
+            let text = state.text();
+            let first = text.offset_to_point(selected.start).row;
+            let mut last = text.offset_to_point(selected.end).row;
+            if selected.end > selected.start && last > first && selected.end == text.line_start_offset(last) { last -= 1; }
