+/// CodeMirror's line-comment command uses the smallest selected indent and
+/// maps the existing caret/selection through the edit. Offsets are relative
+/// UTF-8 bytes; an endpoint after the final selected line is also mapped.
+pub fn comment_edit(text: &str, selection: Range<usize>) -> SourceInsertion {
+    struct Line<'a> { offset: usize, content: &'a str, indent: usize, indent_chars: usize }
+    let mut lines = Vec::new();
+    let mut offset = 0;
+    for line in text.split_inclusive('\n') {
+        let content = line.strip_suffix('\n').unwrap_or(line);
+        let content = content.strip_suffix('\r').unwrap_or(content);
+        let indent_chars = content.chars().take_while(|ch| ch.is_whitespace() || *ch == '\u{feff}').count();
+        let indent = content.char_indices().nth(indent_chars).map_or(content.len(), |(at, _)| at);
+        lines.push(Line { offset, content, indent, indent_chars });
+        offset += line.len();
+    }
+    if lines.is_empty() {
+        lines.push(Line { offset: 0, content: "", indent: 0, indent_chars: 0 });
+    }
+    let single = lines.len() == 1;
+    let comment = lines.iter().any(|line| {
+        (single || line.indent < line.content.len()) && !line.content[line.indent..].starts_with("//")
+    });
+    let min_indent = lines.iter().filter(|line| line.indent < line.content.len())
+        .map(|line| line.indent_chars).min();
+    let mut changes: Vec<(Range<usize>, &str)> = Vec::new();
+    for line in lines {
+        if comment {
+            if single || line.indent < line.content.len() {
+                let indent_chars = min_indent.unwrap_or(line.indent_chars);
+                let indent = line.content.char_indices().nth(indent_chars).map_or(line.content.len(), |(at, _)| at);
+                let at = line.offset + indent;
+                changes.push((at..at, "// "));
+            }
+        } else if line.content[line.indent..].starts_with("//") {
+            let start = line.offset + line.indent;
+            let space = usize::from(line.content[line.indent + 2..].starts_with(' '));
+            changes.push((start..start + 2 + space, ""));
+        }
+    }
+    let map = |position: usize| {
+        let mut removed = 0;
+        let mut inserted = 0;
+        for (range, replacement) in &changes {
+            if position < range.start { break; }
+            if position < range.end { return range.start - removed + inserted + replacement.len(); }
+            removed += range.len();
+            inserted += replacement.len();
+        }
+        position - removed + inserted
+    };
+    let mapped = map(selection.start)..map(selection.end);
+    let mut output = String::with_capacity(text.len() + inserted_comment_capacity(&changes));
+    let mut from = 0;
+    for (range, replacement) in changes {
+        output.push_str(&text[from..range.start]);
+        output.push_str(replacement);
+        from = range.end;
+    }
+    output.push_str(&text[from..]);
+    SourceInsertion { text: output, selection: mapped }
+}
