+            let fade = &mut self.flow.fades[part.index()];
+            if fade.to != target {
+                let from = fade.current();
+                *fade = ChromeFade {
+                    from,
+                    to: target,
+                    started: Instant::now(),
+                    duration: Duration::from_millis(if target == 1. { 200 } else { 1_200 }),
