+    pub(super) fn flow_chrome(
+        &self,
+        part: RoomPart,
+        element: impl IntoElement,
+        cx: &mut Context<Self>,
+    ) -> gpui_kit::AnyElement {
+        let wrapper = div()
+            .id(part.id())
+            .test_support()
+            .track_focus(&self.flow.room_focus[part.index()])
+            .flex_shrink_0()
+            .when(matches!(part, RoomPart::Drawer | RoomPart::Board), |this| this.h_full())
+            .on_hover(cx.listener(move |this, hovering, _, cx| {
+                if *hovering {
+                    this.flow.room_hover.insert(part);
+                    this.flow.reach_since = Some(this.flow.now());
+                } else {
+                    this.flow.room_hover.remove(&part);
+                    if this.flow.room_hover.is_empty() {
+                        this.flow.reach_since = None;
+                    }
+                }
+                cx.notify();
+            }))
+            .child(element);
+        let fade = &self.flow.fades[part.index()];
+        if fade.started.elapsed() >= fade.duration {
+            return wrapper.opacity(fade.to).into_any_element();
+        }
+        let elapsed = fade.started.elapsed().as_secs_f32();
+        let duration = fade.duration.as_secs_f32();
+        let from = fade.from;
+        let to = fade.to;
+        let remaining = fade.duration.saturating_sub(fade.started.elapsed());
+        wrapper
+            .with_animation(
+                (part.id(), fade.generation),
+                Animation::new(remaining),
+                move |wrapper, progress| {
+                    let full = (elapsed + progress * remaining.as_secs_f32()) / duration;
+                    let eased = gpui_kit::base::animation::cubic_bezier(0.25, 0.1, 0.25, 1.)(full.clamp(0., 1.));
+                    wrapper.opacity(from + (to - from) * eased)
+                },
+            )
+            .into_any_element()
+    }
