+            Self {
+                store,
+                record,
+                pending: None,
+                view: None,
+                subscription: None,
+            },
+            warnings,
+        )
+    }
+}
+
+impl WritingRoom {
+    fn marginalia_folio_id(&self) -> String {
+        self.active_document().workspace.as_deref().map_or_else(
+            || self.active.to_string(),
+            |workspace| workspace.folio.id.clone(),
+        )
+    }
+
+    fn marginalia_capabilities(&self) -> MarginaliaCapabilities {
+        MarginaliaCapabilities {
+            persist: self.marginalia.store.is_some(),
+            ..MarginaliaCapabilities::default()
+        }
+    }
+
+    /// Until a native mark reader supplies current IDs, missing knowledge must
