+        let shape = window.text_system().shape_line(
+            self.label.clone(),
+            px(self.size),
+            &[TextRun {
+                len: self.label.len(),
+                font: font(theme::TYPEWRITER_FONT),
+                color: rgb(self.color).into(),
+                ..Default::default()
+            }],
+            None,
+        );
+        let mut cursor = shape.cursor();
+        let parts = self
