+pub fn focus_outline(
+    element: impl IntoElement,
+    offset: f32,
+    radius: f32,
+    color: u32,
+) -> AnyElement {
+    FocusOutline {
+        child: element.into_any_element(),
+        offset,
+        radius,
+        color,
+    }
