+impl WritingRoom {
+    fn rubric_capabilities(&self) -> RubricCapabilities {
+        RubricCapabilities {
+            persist: self.rubric.store.is_some(),
+            refine_dossier: !self.active_document().archived,
+            ..RubricCapabilities::default()
+        }
+    }
