+        if !visible { return; }
+        match event {
+            RubricEvent::SurfaceRequested(surface) => self.open_rubric(surface, window, cx),
+            RubricEvent::BackToDesk => {
+                if self.flush_rubric(window, cx).is_ok() && self.flush(cx).is_ok() {
+                    self.rubric.route = false;
+                    self.focus_writing(window, cx); cx.notify();
