+    pub(super) fn subscribe(&self, window: &mut Window, cx: &mut Context<WritingRoom>) -> Vec<Subscription> {
+        vec![
+            cx.subscribe_in(&self.draft, window, |this, _, event, window, cx| {
+                match event {
+                    InputEvent::Change => {
+                        this.steering.error = None;
+                        cx.notify();
+                    }
+                    InputEvent::PressEnter { shift: false, .. } => {
+                        let input = this.steering.draft.clone();
