+//! Collected Notes/Footnotes use the rich view's immutable note catalog. The
+//! view validates a jump against the current persistent atom before this host
+//! centers its measured marker in the real writing scroller.
+
+use super::*;
+use twyne_desktop::editor::{NoteKind, view::NoteReference};
+
+impl WritingRoom {
+    pub(super) fn collected_notes(
+        &self,
+        editor: &Entity<RichEditorView>,
+        cx: &mut Context<Self>,
+    ) -> Option<gpui_kit::AnyElement> {
+        let references = editor.read(cx).note_references();
+        if references.is_empty() {
+            return None;
+        }
+        let p = *palette(cx);
+        let mut notes = div().id("manuscript-notes").test_support()
+            .mt(px(40.)).pt(px(24.)).border_t_1().border_color(rgb(p.rule))
+            .font_family(SERIF_FONT).text_color(rgb(p.ink_light));
+        let mut first = true;
+        for kind in [NoteKind::Endnote, NoteKind::Footnote] {
+            let items = references.iter().filter(|reference| reference.kind == kind);
+            if !references.iter().any(|reference| reference.kind == kind) { continue; }
+            let label = if kind == NoteKind::Endnote { "Notes" } else { "Footnotes" };
+            let kind_name = if kind == NoteKind::Endnote { "endnote" } else { "footnote" };
+            let color = if kind == NoteKind::Endnote { p.vermilion } else { p.cobalt };
+            let mut group = div().id(SharedString::from(format!("manuscript-notes-{kind_name}")))
+                .test_support().when(!first, |this| this.mt(px(28.)))
+                .child(div().mb(px(8.)).role(Role::Heading)
+                    .child(tracked_typewriter(&label.to_uppercase(), 11.2, 1.568, p.ink_muted)));
+            let mut list = div().role(Role::List).text_size(px(14.72)).line_height(px(23.552));
+            for reference in items {
+                let accessible = format!("Jump to {kind_name} {} in the text", reference.number);
+                let marker = if kind == NoteKind::Footnote { format!("†{}", reference.number) }
+                    else { reference.number.to_string() };
+                let note = reference.clone();
+                let target = editor.clone();
+                let marker = gpui_kit::base::Button::new(SharedString::from(format!("manuscript-note-jump-{kind_name}-{}", reference.number)))
+                    .accessibility_label(accessible).h_auto().min_w(px(16.07424)).p_0()
+                    .rounded_none().flex_shrink_0().font_family(TYPEWRITER_FONT)
+                    .font_weight(FontWeight::SEMIBOLD).text_size(px(11.4816)).line_height(px(18.37056))
