+export function mathCssConsumers(css: string): MathCssConsumers {
+  type Candidate = { value: string; scoped: boolean; important: boolean; order: number };
+  const rows: Record<keyof MathCssConsumers, Candidate[]> = {
+    globalMermaid: [], equation: [], sourcePreview: [],
+  };
+  let order = 0;
