+    postcss.parse(css).walkRules((rule) => {
+      if (!rule.selector.includes("katex-version")) return;
+      const selectors: string[] = [];
+      selectorParser((root) => {
+        root.each((selector) => { selectors.push(selector.toString().trim().replace(/\s+/g, " ")); });
+      }).processSync(rule.selector);
+      rule.walkDecls("content", (declaration) => {
+        const version = /^(["'])(\d+\.\d+\.\d+)\1$/.exec(declaration.value.trim())?.[2] ?? "unknown";
+        for (const selector of selectors) {
+          let consumers: (keyof MathCssConsumers)[] = [];
+          let scoped = true;
+          if (selector === marker) {
+            consumers = ["globalMermaid", "equation", "sourcePreview"];
+            scoped = false;
