+            || selector === `:is(${equationScope}, ${previewScope}) ${marker}`) {
+            consumers = ["equation", "sourcePreview"];
+          }
+          for (const consumer of consumers) {
+            rows[consumer].push({
+              value: rule.parent?.type === "root" ? version : "unknown",
