        let end = after + close + 1;
        let normalized: String = text[start..end].chars().filter(|c| !js_whitespace(*c)).collect();
        matches.push(TagMatch { start, end, is_closing: normalized.starts_with("</") || normalized.ends_with("/>") });
        cursor = end;
    }
    matches
}

