    // The Source partial regex runs against `\\n${visible}`, so an entire
    // beginning tag prefix is withheld too. No trailing whitespace is allowed.
    let starts = std::iter::once(0).chain(visible.match_indices('\\n').map(|(index, _)| index + 1));
    for offset in starts {
        let tail = visible[offset..].trim_start_matches(js_whitespace);
        if !tail.is_empty() && CONTRACT_TAGS.iter().any(|tag| tag.get(..tail.len()).is_some_and(|prefix| prefix.eq_ignore_ascii_case(tail))) {
            let prefix_end = offset.saturating_sub(1);
            return trim_js(&visible[..prefix_end]).to_owned();
        }
    }
    trim_js(visible).to_owned()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum InterviewStreamPhase { Reasoning, Answer }

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct InterviewStreamSnapshot {
    pub text: String,
    pub reasoning: String,
    pub phase: InterviewStreamPhase,
}

fn combined_reasoning(native: &str, tagged: String) -> String {
    let native = trim_js(native);
    if native.is_empty() { return tagged; }
    if tagged.is_empty() || tagged == native { return native.to_owned(); }
    format!("{native}\\n\\n{tagged}")
}

/// Source `createInterviewStreamSnapshot`; ordinary generation snapshots do
/// not filter structured interview contracts. Partial think-tag behavior also
/// remains specific to the original consumer rather than invented here.
pub fn create_interview_stream_snapshot(raw_text: &str, native_reasoning: &str) -> InterviewStreamSnapshot {
    let text = filter_interview_stream_markers(&strip_reasoning_tags(raw_text));
    let phase = if text.is_empty() { InterviewStreamPhase::Reasoning } else { InterviewStreamPhase::Answer };
    InterviewStreamSnapshot { text, reasoning: combined_reasoning(native_reasoning, extract_tagged_reasoning(raw_text)), phase }
}

pub fn text_snapshot(text: String, status: StreamRunStatus) -> GenerationStreamSnapshot {
    let text_status = if text.is_empty() { StreamPartStatus::Pending }
        else if status == StreamRunStatus::Running { StreamPartStatus::Running }
        else { StreamPartStatus::Complete };
    GenerationStreamSnapshot { text, reasoning: String::new(), active_part: ActivePart::None,
        text_status, reasoning_status: StreamPartStatus::Pending, status }
}

pub fn snapshot_from_record(text: String, reasoning: String, phase: InterviewStreamPhase, status: StreamRunStatus) -> GenerationStreamSnapshot {
    let running = status == StreamRunStatus::Running;
    let reasoning_active = running && phase == InterviewStreamPhase::Reasoning;
    GenerationStreamSnapshot {
        text_status: if text.is_empty() { StreamPartStatus::Pending } else if running { StreamPartStatus::Running } else { StreamPartStatus::Complete },
        reasoning_status: if reasoning_active { StreamPartStatus::Running } else if reasoning.is_empty() { StreamPartStatus::Pending } else { StreamPartStatus::Complete },
        active_part: if !running { ActivePart::None } else if reasoning_active { ActivePart::Reasoning } else { ActivePart::Text },
        text, reasoning, status,
    }
}

