+        for expected in expected.iter().cycle().take(expected.len() * 2) {
+            let next = map.next(focused.as_ref()).unwrap();
+            assert_eq!(next.id, expected.id);
+            focused = Some(next.id);
+        }
+        let mut focused = None;
+        for expected in expected.iter().rev().cycle().take(expected.len() * 2) {
+            let previous = map.prev(focused.as_ref()).unwrap();
+            assert_eq!(previous.id, expected.id);
+            focused = Some(previous.id);
+        }
+    }
+
+    #[test]
+    fn repeated_input_tracking_does_not_trap_reverse_tab() {
+        let focus_map = Arc::new(FocusMap::default());
+        let before = FocusHandle::new(&focus_map).tab_stop(true);
+        let input = FocusHandle::new(&focus_map).tab_stop(true);
+        let after = FocusHandle::new(&focus_map).tab_stop(true);
+        let mut map = TabStopMap::default();
+        map.insert(&before);
+        // A container, its input wrapper and the actual input may all track
