+enum Frame<'a> {
+    Nodes { nodes: &'a [Node], consumed: usize },
+    Text(&'a str),
+    Character(char),
+}
+#[derive(Clone, Copy)]
+enum Piece<'a> { Node(&'a Node), Character(char) }
+struct ProjectionCursor<'a> { frames: Vec<Frame<'a>>, reverse: bool }
+impl<'a> ProjectionCursor<'a> {
+    fn new(document: &'a RichDocument, reverse: bool) -> Self {
+        Self { frames: vec![Frame::Nodes { nodes: document.nodes(), consumed: 0 }], reverse }
+    }
+    fn peek(&mut self) -> Option<Piece<'a>> {
+        loop {
+            match self.frames.last_mut()? {
+                Frame::Nodes { nodes, consumed } => {
+                    if *consumed == nodes.len() { self.frames.pop(); continue; }
+                    let index = if self.reverse { nodes.len() - 1 - *consumed } else { *consumed };
+                    let node = &nodes[index];
+                    if node.projection_len() == 0 { *consumed += 1; continue; }
+                    return Some(Piece::Node(node));
+                }
+                Frame::Text(text) => {
+                    let character = if self.reverse { text.chars().next_back() } else { text.chars().next() };
+                    if let Some(character) = character { return Some(Piece::Character(character)); }
+                    self.frames.pop();
+                }
+                Frame::Character(character) => return Some(Piece::Character(*character)),
+            }
+        }
+    }
+    fn advance(&mut self) {
+        match self.frames.last_mut().expect("a peeked projection piece") {
+            Frame::Nodes { consumed, .. } => *consumed += 1,
+            Frame::Text(text) => {
+                let character = if self.reverse { text.chars().next_back() } else { text.chars().next() }.unwrap();
+                *text = if self.reverse { &text[..text.len() - character.len_utf8()] } else { &text[character.len_utf8()..] };
+            }
+            Frame::Character(_) => { self.frames.pop(); }
+        }
+    }
+    fn expand(&mut self, node: &'a Node) {
+        self.advance();
+        match node.data() {
+            NodeData::Text(text) => self.frames.push(Frame::Text(text)),
+            NodeData::Comment(_) => {}
+            NodeData::Element(element) => {
+                if element.kind.is_atom() { self.frames.push(Frame::Character('\u{fffc}')); }
+                else if element.kind == NodeKind::HardBreak { self.frames.push(Frame::Character('\n')); }
+                else if element.kind != NodeKind::NonContent {
+                    if element.is_text_block && !self.reverse { self.frames.push(Frame::Character('\n')); }
+                    self.frames.push(Frame::Nodes { nodes: &element.children, consumed: 0 });
+                    if element.is_text_block && self.reverse { self.frames.push(Frame::Character('\n')); }
+                }
+            }
+        }
+    }
+}
+fn shared_projection(before: &RichDocument, after: &RichDocument, reverse: bool, limit: usize) -> usize {
+    let mut a = ProjectionCursor::new(before, reverse);
+    let mut b = ProjectionCursor::new(after, reverse);
+    let mut count = 0;
+    while count < limit {
+        match (a.peek(), b.peek()) {
+            (Some(Piece::Node(a_node)), Some(Piece::Node(b_node)))
+                if a_node.shares_storage_with(b_node) && a_node.projection_len() <= limit - count =>
+            {
+                count += a_node.projection_len();
+                a.advance(); b.advance();
+            }
+            (Some(Piece::Node(node)), _) => a.expand(node),
+            (_, Some(Piece::Node(node))) => b.expand(node),
+            (Some(Piece::Character(a_char)), Some(Piece::Character(b_char))) if a_char == b_char => {
+                count += 1; a.advance(); b.advance();
+            }
+            _ => break,
+        }
+    }
+    count
+}
