+//! Writer-owned templates and per-folio material. The library Store retains
+//! the OS lock; clones serialize these metadata writes and verify readback.
+use super::{notebook::{empty_notebook, normalize_notebook}, saved::{decode_saved_tools, normalize_saved_tool}, seed::ToolKind};
+use anyhow::{Context, Result, ensure};
+use serde::{Deserialize, Serialize};
+use serde_json::{Value, json};
+use std::{collections::BTreeMap, fs::File, io::{Read, Write}, path::{Path, PathBuf}, sync::{Arc, Mutex}, time::{SystemTime, UNIX_EPOCH}};
+use tempfile::NamedTempFile;
+use uuid::Uuid;
+
+const MAX_METADATA_BYTES: usize = 16 * 1024 * 1024;
+const MAX_SAVED: usize = 24;
+
+#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
+#[serde(rename_all = "camelCase", deny_unknown_fields)]
+struct Record {
+    version: u8,
+    generation: u64,
+    saved_tools: Vec<Value>,
+    notebooks: BTreeMap<String, Value>,
+}
+impl Default for Record {
+    fn default() -> Self { Self { version: 1, generation: 0, saved_tools: Vec::new(), notebooks: BTreeMap::new() } }
+}
+#[derive(Clone)]
+pub struct ToolStore { path: PathBuf, writer: Arc<Mutex<()>> }
+#[derive(Clone)]
+pub struct ToolWriteAck {
+    pub generation: u64,
+    pub saved_tools: Vec<Value>,
+    pub saved_id: Option<String>,
+}
+impl ToolStore {
+    pub fn open(library_root: &Path) -> Result<Self> {
+        ensure!(library_root.is_dir(), "The writing library is unavailable.");
+        let store = Self { path: library_root.join("writing-tools.json"), writer: Arc::new(Mutex::new(())) };
+        store.read()?;
+        Ok(store)
+    }
+    pub fn load_saved(&self) -> Result<ToolWriteAck> {
+        let _writer = self.writer.lock().map_err(|_| anyhow::anyhow!("The writing tools save was interrupted."))?;
+        let record = self.read()?;
+        Ok(ToolWriteAck { generation: record.generation, saved_tools: decode_saved_tools(&json!(record.saved_tools))?, saved_id: None })
+    }
+    pub fn load_notebook(&self, folio: &str) -> Result<Value> {
+        if folio.is_empty() { return Ok(empty_notebook()); }
+        let _writer = self.writer.lock().map_err(|_| anyhow::anyhow!("The writing tools save was interrupted."))?;
+        let record = self.read()?;
+        Ok(normalize_notebook(record.notebooks.get(folio).unwrap_or(&Value::Null)))
+    }
+    pub fn keep(&self, kind: ToolKind, name: &str, config: Value) -> Result<ToolWriteAck> {
+        let _writer = self.writer.lock().map_err(|_| anyhow::anyhow!("The writing tools save was interrupted."))?;
