fn js_number_text(number: &serde_json::Number) -> String {
    let value = number.as_f64().unwrap_or(f64::NAN);
    if value == 0. { return "0".into(); }
    let raw = serde_json::Number::from_f64(value).expect("JSON numbers are finite").to_string();
    let (mantissa, exponent) = raw.split_once(['e', 'E']).map_or((raw.as_str(), 0), |(m, e)| (m, e.parse::<i32>().unwrap()));
    let negative = mantissa.starts_with('-');
    let mantissa = mantissa.trim_start_matches('-');
    let dot = mantissa.find('.').unwrap_or(mantissa.len()) as i32;
    let mut digits = mantissa.replace('.', "");
    while digits.ends_with('0') && digits.len() > 1 { digits.pop(); }
    let decimal = dot + exponent;
    let sign = if negative { "-" } else { "" };
    if value.abs() >= 1e-6 && value.abs() < 1e21 {
        if decimal <= 0 { return format!("{sign}0.{}{digits}", "0".repeat((-decimal) as usize)); }
        if decimal as usize >= digits.len() { return format!("{sign}{digits}{}", "0".repeat(decimal as usize - digits.len())); }
        return format!("{sign}{}.{}", &digits[..decimal as usize], &digits[decimal as usize..]);
    }
    // Scientific notation's first nonzero digit carries the parseInt prefix.
    let leading_zeros = digits.bytes().take_while(|byte| *byte == b'0').count();
    let digits = &digits[leading_zeros..];
    let exp = decimal - leading_zeros as i32 - 1;
    let fraction = if digits.len() == 1 { String::new() } else { format!(".{}", &digits[1..]) };
    format!("{sign}{}{fraction}e{}{exp}", &digits[..1], if exp >= 0 { "+" } else { "" })
}

fn js_string(value: Option<&Value>) -> String {
    match value {
        None => "undefined".into(),
        Some(Value::Null) => "null".into(),
        Some(Value::Bool(value)) => value.to_string(),
        Some(Value::Number(value)) => js_number_text(value),
        Some(Value::String(value)) => value.clone(),
        Some(Value::Array(values)) => values.iter().map(|value| if value.is_null() { String::new() } else { js_string(Some(value)) }).collect::<Vec<_>>().join(","),
        Some(Value::Object(_)) => "[object Object]".into(),
    }
}

fn js_number(value: Option<&Value>) -> f64 {
    match value {
        None => f64::NAN,
        Some(Value::Null) => 0.,
        Some(Value::Bool(value)) => if *value { 1. } else { 0. },
        Some(Value::Number(value)) => value.as_f64().unwrap_or(f64::NAN),
        Some(value) => {
            let text = js_string(Some(value));
            let text = text.trim_matches(js_whitespace);
            if text.is_empty() { return 0.; }
            if matches!(text, "Infinity" | "+Infinity") { return f64::INFINITY; }
            if text == "-Infinity" { return f64::NEG_INFINITY; }
            for (prefix, radix) in [("0x", 16), ("0X", 16), ("0b", 2), ("0B", 2), ("0o", 8), ("0O", 8)] {
                if let Some(digits) = text.strip_prefix(prefix) {
                    if digits.is_empty() { return f64::NAN; }
                    return digits.chars().try_fold(0., |value, digit| digit.to_digit(radix).map(|digit| value * f64::from(radix) + f64::from(digit))).unwrap_or(f64::NAN);
                }
            }
            static DECIMAL: std::sync::OnceLock<regex::Regex> = std::sync::OnceLock::new();
            if DECIMAL.get_or_init(|| regex::Regex::new(r"^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$").unwrap()).is_match(text) {
                text.parse().unwrap_or(f64::NAN)
            } else { f64::NAN }
        }
    }
}

fn js_truthy(value: Option<&Value>) -> bool {
    match value {
        None | Some(Value::Null) => false,
        Some(Value::Bool(value)) => *value,
        Some(Value::Number(value)) => value.as_f64().is_some_and(|number| number != 0. && !number.is_nan()),
        Some(Value::String(value)) => !value.is_empty(),
        Some(_) => true,
    }
}

fn js_property(value: &Value, key: &str) -> Option<Value> {
    if let Some(object) = value.as_object() {
        return object.get(key).cloned().or_else(|| {
            matches!(key, "__proto__" | "constructor" | "toString" | "toLocaleString" | "valueOf" | "hasOwnProperty" | "isPrototypeOf" | "propertyIsEnumerable" | "__defineGetter__" | "__defineSetter__" | "__lookupGetter__" | "__lookupSetter__").then(|| Value::String("NaN".into()))
        });
    }
    if key == "length" {
        if let Some(values) = value.as_array() { return Some(json!(values.len())); }
        if let Some(text) = value.as_str() { return Some(json!(text.encode_utf16().count())); }
    }
    let index = key.parse::<usize>().ok().filter(|index| index.to_string() == key)?;
    match value {
        Value::Array(values) => values.get(index).cloned(),
        Value::String(text) => text.encode_utf16().nth(index).map(|unit| Value::String(String::from_utf16_lossy(&[unit]))),
        _ => None,
    }
}
