+//! Source-styled fields over the Kit's retained native editing engine.
+use crate::theme::{Palette, SERIF_FONT};
+use gpui_kit::base::input::{Input, InputBase, InputBaseState, InputModeKind, InputState};
+use gpui_kit::prelude::*;
