+interface CommandResult { code: number; stdout: string; stderr: string; }
+export type CredentialCommand = (args: string[], secret?: string) => Promise<CommandResult>;
+async function boundedText(stream: ReadableStream<Uint8Array>): Promise<string> {
+  const reader = stream.getReader();
+  const chunks: Uint8Array[] = [];
+  let length = 0;
+  try {
+    for (;;) {
+      const chunk = await reader.read();
+      if (chunk.done) break;
+      length += chunk.value.byteLength;
+      if (length > 65_536) throw new ConnectedError("unavailable");
+      chunks.push(chunk.value);
+    }
+  } finally { reader.releaseLock(); }
+  const bytes = new Uint8Array(length);
+  let offset = 0;
+  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
+  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
+}
+async function secretTool(args: string[], secret?: string): Promise<CommandResult> {
+  const executable = Bun.which("secret-tool");
+  if (!executable) throw new ConnectedError("unavailable");
+  // Direct exec with argument arrays, no shell. The credential is supplied on
+  // stdin, never argv, environment, a temporary file or an application log.
+  const child = Bun.spawn([executable, ...args], {
+    stdin: secret === undefined ? "ignore" : new Blob([secret]),
+    stdout: "pipe", stderr: "pipe",
+  });
+  const timeout = setTimeout(() => child.kill("SIGKILL"), 15_000);
+  try {
+    const [stdout, stderr, code] = await Promise.all([
+      boundedText(child.stdout), boundedText(child.stderr), child.exited,
+    ]);
+    return { code, stdout, stderr };
+  } catch {
+    child.kill("SIGKILL");
+    await child.exited;
+    throw new ConnectedError("unavailable");
+  } finally { clearTimeout(timeout); }
+}
