+gpui_kit::actions!(twyne_table_picker, [Up, Down, Left, Right, Home, End, Insert, Cancel]);
+const KEY_CONTEXT: &str = "TwyneTablePicker";
+
+pub fn init(cx: &mut App) {
+    cx.bind_keys([
+        KeyBinding::new("up", Up, Some(KEY_CONTEXT)),
+        KeyBinding::new("down", Down, Some(KEY_CONTEXT)),
+        KeyBinding::new("left", Left, Some(KEY_CONTEXT)),
+        KeyBinding::new("right", Right, Some(KEY_CONTEXT)),
+        KeyBinding::new("home", Home, Some(KEY_CONTEXT)),
+        KeyBinding::new("end", End, Some(KEY_CONTEXT)),
+        KeyBinding::new("enter", Insert, Some(KEY_CONTEXT)),
+        KeyBinding::new("escape", Cancel, Some(KEY_CONTEXT)),
+    ]);
+}
+
+#[derive(Clone, Debug)]
+pub enum TablePickerEvent { Insert(Dimensions), Cancel }
+
+pub struct TablePickerView {
+    focus: FocusHandle,
+    cells: Vec<FocusHandle>,
+    selected: Dimensions,
+    _subscriptions: Vec<Subscription>,
+}
+impl EventEmitter<TablePickerEvent> for TablePickerView {}
+impl Focusable for TablePickerView {
+    fn focus_handle(&self, _: &App) -> FocusHandle { self.focus.clone() }
+}
+
+impl TablePickerView {
+    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
+        init(cx);
+        let focus = cx.focus_handle().tab_stop(true);
+        let cells = (0..DEFAULT_ROWS * DEFAULT_COLUMNS).map(|_| cx.focus_handle().tab_stop(true)).collect::<Vec<_>>();
+        let subscriptions = cells.iter().enumerate().map(|(index, focus)| {
+            window.on_focus(focus, cx, cx.listener(move |this, _, _, cx| {
+                this.select(Dimensions { rows: index / DEFAULT_COLUMNS + 1, columns: index % DEFAULT_COLUMNS + 1 }, cx);
+            }))
+        }).collect();
+        Self { focus, cells, selected: Dimensions { rows: 1, columns: 1 }, _subscriptions: subscriptions }
+    }
+    pub fn selected(&self) -> Dimensions { self.selected }
+    fn limits() -> Dimensions { Dimensions { rows: DEFAULT_ROWS, columns: DEFAULT_COLUMNS } }
+    fn select(&mut self, dimensions: Dimensions, cx: &mut Context<Self>) {
+        let next = dimensions.clamped(Self::limits());
+        if self.selected != next { self.selected = next; cx.notify(); }
+    }
+    fn resize(&mut self, direction: Direction, cx: &mut Context<Self>) {
+        self.select(self.selected.moved(direction, Self::limits()), cx);
+    }
+}
