+    #[derive(serde::Deserialize)]
+    struct Case { current: Dimensions, limits: Dimensions, expected: Dimensions, direction: Option<Direction> }
+    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../fixtures/insert-menu/source-table-grid-cases.json")).unwrap();
+    assert_eq!(fixture["constants"], serde_json::json!({ "defaultRows": table_grid::DEFAULT_ROWS, "defaultColumns": table_grid::DEFAULT_COLUMNS, "maxRows": table_grid::MAX_ROWS, "maxColumns": table_grid::MAX_COLUMNS }));
+    for entry in fixture["moves"].as_array().unwrap().iter().chain(fixture["clamps"].as_array().unwrap()) {
+        let case: Case = serde_json::from_value(entry.clone()).unwrap();
+        let actual = if let Some(direction) = case.direction { case.current.moved(direction, case.limits) } else { case.current.clamped(case.limits) };
+        assert_eq!(actual, case.expected, "{entry}");
+    }
+    let selection = Dimensions { rows: 2, columns: 4 };
